CREATE POLICY "organizzatore carica locandine" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'locandine' AND EXISTS (SELECT 1 FROM public.eventi e WHERE e.organizzatore_id = auth.uid() AND name LIKE e.id::text || '-%'));
CREATE POLICY "organizzatore aggiorna locandine" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'locandine' AND EXISTS (SELECT 1 FROM public.eventi e WHERE e.organizzatore_id = auth.uid() AND name LIKE e.id::text || '-%')) WITH CHECK (bucket_id = 'locandine' AND EXISTS (SELECT 1 FROM public.eventi e WHERE e.organizzatore_id = auth.uid() AND name LIKE e.id::text || '-%'));
CREATE POLICY "organizzatore legge locandine" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'locandine' AND EXISTS (SELECT 1 FROM public.eventi e WHERE e.organizzatore_id = auth.uid() AND name LIKE e.id::text || '-%'));